package earlyrentalhttp

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"

	"github.com/HernanEspinozaDev/espaciGo/internal/earlyrental"
)

const maxCommandBodyBytes = 16 << 10

var (
	ErrMalformedCommandBody = errors.New("malformed early-rental command body")
	ErrInvalidCommandValue  = errors.New("invalid early-rental command value")
)

// Actor and timestamps come from server context; revision comes from If-Match;
// payment movement IDs are generated by the server. None belong in the JSON body.
func DecodeCommandBody(kind earlyrental.CommandKind, body []byte) (earlyrental.Command, error) {
	command := earlyrental.Command{Kind: kind}
	if len(body) == 0 || len(body) > maxCommandBodyBytes {
		return earlyrental.Command{}, ErrMalformedCommandBody
	}

	switch kind {
	case earlyrental.CommandConfirmIdentity, earlyrental.CommandSendPayment, earlyrental.CommandReceivePayment:
		var request struct{}
		if err := decodeCommandJSON(body, &request); err != nil {
			return earlyrental.Command{}, ErrMalformedCommandBody
		}
	case earlyrental.CommandAcceptContract:
		var request struct {
			ContractVersion *int64  `json:"contract_version"`
			ContractDigest  *string `json:"contract_digest"`
		}
		if err := decodeCommandJSON(body, &request, "contract_version", "contract_digest"); err != nil {
			return earlyrental.Command{}, ErrMalformedCommandBody
		}
		if request.ContractVersion == nil || request.ContractDigest == nil {
			return earlyrental.Command{}, ErrMalformedCommandBody
		}
		if *request.ContractVersion <= 0 || !earlyrental.ValidContractDigest(*request.ContractDigest) {
			return earlyrental.Command{}, ErrInvalidCommandValue
		}
		command.ContractVersion = *request.ContractVersion
		command.ContractDigest = *request.ContractDigest
	case earlyrental.CommandReject, earlyrental.CommandCancel:
		var request struct {
			ReasonCode *string `json:"reason_code"`
		}
		if err := decodeCommandJSON(body, &request, "reason_code"); err != nil {
			return earlyrental.Command{}, ErrMalformedCommandBody
		}
		if request.ReasonCode == nil {
			return earlyrental.Command{}, ErrMalformedCommandBody
		}
		if !earlyrental.ValidReasonCode(*request.ReasonCode) {
			return earlyrental.Command{}, ErrInvalidCommandValue
		}
		command.ReasonCode = *request.ReasonCode
	default:
		return earlyrental.Command{}, ErrMalformedCommandBody
	}
	return command, nil
}

func decodeCommandJSON(body []byte, target any, allowedFields ...string) error {
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 || len(trimmed) > maxCommandBodyBytes {
		return ErrMalformedCommandBody
	}
	if err := validateCommandJSONObject(trimmed, allowedFields); err != nil {
		return err
	}
	decoder := json.NewDecoder(bytes.NewReader(trimmed))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return ErrMalformedCommandBody
	}
	return nil
}

func validateCommandJSONObject(body []byte, allowedFields []string) error {
	decoder := json.NewDecoder(bytes.NewReader(body))
	token, err := decoder.Token()
	if err != nil {
		return err
	}
	delimiter, ok := token.(json.Delim)
	if !ok || delimiter != '{' {
		return ErrMalformedCommandBody
	}
	allowed := make(map[string]struct{}, len(allowedFields))
	for _, field := range allowedFields {
		allowed[field] = struct{}{}
	}
	if err := scanCommandObject(decoder, allowed); err != nil {
		return err
	}
	if _, err := decoder.Token(); err != io.EOF {
		return ErrMalformedCommandBody
	}
	return nil
}

func scanCommandObject(decoder *json.Decoder, allowed map[string]struct{}) error {
	seen := make(map[string]struct{})
	for decoder.More() {
		token, err := decoder.Token()
		if err != nil {
			return err
		}
		key, ok := token.(string)
		if !ok {
			return ErrMalformedCommandBody
		}
		if _, exists := seen[key]; exists {
			return ErrMalformedCommandBody
		}
		seen[key] = struct{}{}
		if _, exists := allowed[key]; !exists {
			return ErrMalformedCommandBody
		}
		if err := scanCommandValue(decoder); err != nil {
			return err
		}
	}
	closing, err := decoder.Token()
	if err != nil {
		return err
	}
	if delimiter, ok := closing.(json.Delim); !ok || delimiter != '}' {
		return ErrMalformedCommandBody
	}
	return nil
}

func scanCommandValue(decoder *json.Decoder) error {
	token, err := decoder.Token()
	if err != nil {
		return err
	}
	delimiter, ok := token.(json.Delim)
	if !ok {
		return nil
	}
	switch delimiter {
	case '{':
		return scanCommandObject(decoder, nil)
	case '[':
		for decoder.More() {
			if err := scanCommandValue(decoder); err != nil {
				return err
			}
		}
		closing, err := decoder.Token()
		if err != nil {
			return err
		}
		if delimiter, ok := closing.(json.Delim); !ok || delimiter != ']' {
			return ErrMalformedCommandBody
		}
		return nil
	default:
		return ErrMalformedCommandBody
	}
}
